mapper.insert:
MERGE INTO hashtags h USING ( SELECT DISTINCT column_value AS tag_name FROM TABLE(sys.odcivarchar2list(
#{tagName}
)) ) src ON (h.tag_name = src.tag_name) WHEN NOT MATCHED THEN INSERT ( tag_name, created_at ) VALUES ( src.tag_name, SYSTIMESTAMP )

INSERT INTO post_hashtags ( post_id, hashtag_id, created_at ) SELECT #{postId}, h.hashtag_id, SYSTIMESTAMP FROM hashtags h JOIN ( SELECT DISTINCT column_value AS tag_name FROM TABLE(sys.odcivarchar2list(
#{tagName}
)) ) src ON h.tag_name = src.tag_name WHERE NOT EXISTS ( SELECT 1 FROM post_hashtags ph WHERE ph.post_id = #{postId} AND ph.hashtag_id = h.hashtag_id )
